import os, shutil, py_compile, base64

J = os.path.expanduser("~/.jarvis")
CORE = os.path.join(J, "core.py")
BAK = CORE + ".bak8"
PWA = os.path.join(J, "pwa")
os.makedirs(PWA, exist_ok=True)

MANIFEST = '{\n  "name": "JARVIS",\n  "short_name": "JARVIS",\n  "description": "Your personal AI assistant - chat, brain, image, video, build, voice",\n  "start_url": "/",\n  "display": "standalone",\n  "background_color": "#05080c",\n  "theme_color": "#05080c",\n  "icons": [\n    { "src": "/icons/icon-192.png", "sizes": "192x192", "type": "image/png" },\n    { "src": "/icons/icon-512.png", "sizes": "512x512", "type": "image/png", "purpose": "any maskable" }\n  ]\n}\n'
SW = 'const C = "jarvis-v1";\nself.addEventListener("install", function(e){ self.skipWaiting(); });\nself.addEventListener("activate", function(e){ e.waitUntil(self.clients.claim()); });\nself.addEventListener("fetch", function(e){\n  var u = new URL(e.request.url);\n  if (u.pathname.indexOf("/api") === 0) {\n    e.respondWith(fetch(e.request).catch(function(){ return caches.match(e.request); }));\n    return;\n  }\n  e.respondWith(\n    caches.open(C).then(function(c){\n      return c.match(e.request).then(function(cached){\n        var net = fetch(e.request).then(function(r){\n          if (r.ok) c.put(e.request, r.clone());\n          return r;\n        }).catch(function(){ return cached; });\n        return cached || net;\n      });\n    })\n  );\n});\n'
I192 = ''
I512 = ''

open(os.path.join(PWA, "manifest.webmanifest"), "w").write(MANIFEST)
open(os.path.join(PWA, "sw.js"), "w").write(SW)
open(os.path.join(PWA, "icon-192.png"), "wb").write(base64.b64decode(I192))
open(os.path.join(PWA, "icon-512.png"), "wb").write(base64.b64decode(I512))
print("pwa assets written to", PWA)

ROUTES = '\n@app.get("/manifest.webmanifest")\ndef _pwa_manifest():\n    try:\n        return Response(open(os.path.join(APP_DIR, "pwa", "manifest.webmanifest")).read(),\n                        media_type="application/manifest+json")\n    except Exception:\n        return Response("{}", media_type="application/manifest+json")\n\n\n@app.get("/sw.js")\ndef _pwa_sw():\n    try:\n        return Response(open(os.path.join(APP_DIR, "pwa", "sw.js")).read(),\n                        media_type="application/javascript")\n    except Exception:\n        return Response("// no sw", media_type="application/javascript")\n\n\n@app.get("/icons/icon-192.png")\ndef _pwa_i192():\n    return FileResponse(os.path.join(APP_DIR, "pwa", "icon-192.png"))\n\n\n@app.get("/icons/icon-512.png")\ndef _pwa_i512():\n    return FileResponse(os.path.join(APP_DIR, "pwa", "icon-512.png"))\n'
HEAD_TAGS = '<link rel="manifest" href="/manifest.webmanifest">\n<meta name="theme-color" content="#05080c">\n<meta name="mobile-web-app-capable" content="yes">\n<meta name="apple-mobile-web-app-capable" content="yes">\n<meta name="apple-mobile-web-app-status-bar-style" content="black-translucent">\n<meta name="apple-mobile-web-app-title" content="JARVIS">\n<link rel="apple-touch-icon" href="/icons/icon-192.png">\n<script>if(\'serviceWorker\' in navigator){navigator.serviceWorker.register(\'/sw.js\');}</script>'

src = open(CORE).read()
shutil.copy(CORE, BAK)

if "FileResponse" not in src:
    src = src.replace("from fastapi.responses import HTMLResponse",
                      "from fastapi.responses import HTMLResponse, Response, FileResponse", 1)
    print("core.py: added Response/FileResponse imports")

if "def _pwa_manifest" not in src:
    anchor = 'if __name__ == "__main__":'
    if anchor in src:
        src = src.replace(anchor, ROUTES + "\n" + anchor, 1)
        print("core.py: PWA routes added")
    else:
        src = src.rstrip() + "\n" + ROUTES + "\n"
        print("core.py: PWA routes appended")

if 'rel="manifest"' not in src:
    s2 = src.replace("</head>", HEAD_TAGS + "\n</head>", 1)
    if s2 != src:
        src = s2
        print("core.py: PWA link tags injected into UI head")
    else:
        print("WARNING: could not inject PWA tags (</head> not found)")

open(CORE, "w").write(src)
try:
    py_compile.compile(CORE, doraise=True)
    print("core.py COMPILES OK")
except Exception as e:
    shutil.copy(BAK, CORE)
    print("PATCH FAILED - restored backup:", e)
    raise SystemExit(1)

import time, subprocess, urllib.request
PY = "python3"
vp = os.path.expanduser("~/omni-jarvis/venv/bin/python")
if os.path.exists(vp):
    PY = vp
subprocess.run(["pkill", "-f", "core.py"])
time.sleep(1)
log = open("/tmp/jarvis.log", "w")
subprocess.Popen([PY, CORE], stdout=log, stderr=subprocess.STDOUT, start_new_session=True)
time.sleep(2)
try:
    h = urllib.request.urlopen("http://127.0.0.1:8000/health", timeout=5).read().decode()
    print("HEALTH:", h)
except Exception as e:
    print("CHECK FAILED:", e, "- see /tmp/jarvis.log")
